 10 | /**
 11 |  * Custom error class for API errors
 12 |  */
 13 | export class ApiError extends Error {
 14 |   constructor(
 15 |     message: string,
 16 |     public statusCode: number,
 17 |     public retryable: boolean = false
 18 |   ) {
 19 |     super(message);
 20 |     this.name = 'ApiError';
 21 |   }
 22 | }
